#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Render the bilingual research library from data/papers.json (standard library)."""
import json,csv,html
from datetime import date
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def build():
 data=json.loads((ROOT/'data/papers.json').read_text());papers=data['papers'];esc=lambda x:html.escape(str(x),quote=True)
 updated=date.fromisoformat(data['updated_at']);updated_en=f'{updated.strftime("%B")} {updated.day}, {updated.year}';updated_zh=f'{updated.year} 年 {updated.month} 月 {updated.day} 日'
 evidence_labels={'full_text_assessed':('全文评估','Full-text assessed'),'abstract_html_provisional':('摘要/HTML 暂留','Abstract/HTML provisional')}
 for en in [False,True]:
  base='../' if en else '';directory=ROOT/'en' if en else ROOT;t=lambda zh,english:english if en else zh
  games={g['id']:g['title'] for g in json.loads((directory/'data/games.json').read_text())['games']}
  cards=[]
  for p in sorted(papers,key=lambda x:(-x['year'],x['title'].lower())):
   topic=p['topic'] if en else data['topics'][p['topic']];kind=p['publication_type'] if en else data['publication_types'][p['publication_type']]
   status=evidence_labels.get(p.get('evidence_status'))
   status_meta=f'<span>{esc(status[1 if en else 0])}</span>' if status else ''
   related=' · '.join(f'<a href="./?entry={esc(i)}">{esc(games[i])} ↗</a>' for i in p['related_game_ids'])
   versions=' · '.join(f'<a href="#{esc(i)}">{t("相关发表版本","Related publication")} ↗</a>' for i in p.get('related_paper_ids',[]))
   doi=f'<a href="https://doi.org/{esc(p["doi"])}" target="_blank" rel="noopener noreferrer">DOI ↗</a>' if p['doi'] else ''
   cards.append(f'''<article class="paper" id="{esc(p['id'])}" data-topic="{esc(p['topic'])}" data-type="{esc(p['publication_type'])}" data-year="{p['year']}">
<div class="paper-meta"><span>{p['year']}</span><span>{esc(kind)}</span><span>{esc(topic)}</span>{status_meta}</div>
<h2><a href="{esc(p['url'])}" target="_blank" rel="noopener noreferrer">{esc(p['title'])}</a></h2>
<p class="paper-authors">{esc(p['authors'])}</p><p class="paper-venue">{esc(p['venue'])}</p>
<p class="paper-summary">{esc(p['summary_en' if en else 'summary_zh'])}</p>
<div class="paper-links"><a href="{esc(p['url'])}" target="_blank" rel="noopener noreferrer">{t('阅读原文','Read publication')} ↗</a>{doi}<a href="{esc(p['discovery_source'])}" target="_blank" rel="noopener noreferrer">{t('收录来源','Collection source')} ↗</a><a href="#{esc(p['id'])}" class="paper-permalink">{t('条目链接','Permalink')}</a></div>
{('<p class="paper-related">'+t('关联游戏：','Related games: ')+related+'</p>') if related else ''}
{('<p class="paper-related">'+versions+'</p>') if versions else ''}</article>''')
  def options(key,mapping):return ''.join(f'<option value="{esc(x)}">{esc(x if en else mapping[x])}</option>' for x in sorted(set(p[key] for p in papers)))
  path='research.html';other='../research.html' if en else 'en/research.html';issue='paper-en.yml' if en else 'paper-zh.yml'
  content=f'''<!doctype html><html lang="{'en' if en else 'zh-CN'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{t('眼动研究文献库：按主题、年份和文献类型检索，附双语简介与原文来源。','Eye-tracking research with topic, year and publication-type filters, bilingual summaries and original sources.')}"><title>{t('研究论文','Research')} · Gaze Atlas</title><link rel="stylesheet" href="{base}style.css?v=20261022-research"><link rel="stylesheet" href="{base}research.css?v=20261022-research"><script src="{base}research.js?v=20261022-research" defer></script><script src="{base}community.js?v=20261022-research" defer></script></head><body>
<a class="skip" href="#papers">{t('跳到文献','Skip to publications')}</a><header><a class="brand" href="./"><span class="eye">◉</span> GAZE ATLAS</a><nav aria-label="{t('主导航','Main navigation')}"><a href="./">{t('游戏库','Games')}</a><a href="research.html" aria-current="page">{t('研究论文','Research')}</a><a href="analysis.html">{t('研究分析','Analysis')}</a><a href="review.html">{t('综述与方法','Review & methods')}</a>{('<a href="'+other+'">English</a>') if not en else ''}<details class="community-menu"><summary>{t('参与共建','Contribute')} ⌄</summary><div class="community-dropdown"><a href="#contribute-paper">{t('提交论文','Submit a paper')}</a><a href="contribute.html">{t('提交游戏与贡献指南','Submit a game & guide')}</a><a href="contributors.html">{t('贡献者致谢','Contributors')}</a></div></details></nav></header>
<main class="research-page"><section class="research-hero"><div><p class="eyebrow">GAZE ATLAS / RESEARCH</p><h1>{t('目光背后的研究','Research behind the gaze.')}</h1><p class="intro">{t('探索眼动测量、游戏交互、视觉训练与人类表现的研究。<br>从一篇论文，找到方法、来源与相关游戏。','Explore eye movement measurement, game interaction, visual training and human performance.<br>Follow a paper to its methods, sources and related games.')}</p></div><div class="research-total"><strong>{len(papers)}</strong><span>{t('文献条目','publications')}</span><small>{min(p['year'] for p in papers)} — {max(p['year'] for p in papers)}</small></div></section>
<div class="research-downloads"><span>{t('更新于 '+updated_zh,'Updated '+updated_en)}</span><a href="{base}data/papers.json" download>↓ JSON</a><a href="{base}data/papers.csv" download>↓ CSV</a><a href="#contribute-paper">{t('提交论文','Submit a paper')} ↗</a></div>
<section class="paper-controls" aria-label="{t('文献筛选','Publication filters')}"><label class="paper-search">{t('关键词','Search')}<input type="search" id="paper-search" placeholder="{t('题目、作者、期刊或关键词…','Title, author, venue or keyword…')}"></label><label>{t('研究主题','Topic')}<select id="paper-topic"><option value="">{t('全部主题','All topics')}</option>{options('topic',data['topics'])}</select></label><label>{t('文献类型','Publication type')}<select id="paper-type"><option value="">{t('全部类型','All types')}</option>{options('publication_type',data['publication_types'])}</select></label><label>{t('年份','Year')}<select id="paper-year"><option value="">{t('全部年份','All years')}</option>{''.join(f'<option>{y}</option>' for y in sorted(set(p['year'] for p in papers),reverse=True))}</select></label><button id="paper-reset" type="button">{t('重置','Reset')}</button></section>
<div class="research-list-heading"><h2>{t('文献目录','Publication library')}</h2><p id="paper-count" role="status" aria-live="polite">{len(papers)} {t('条文献','publications')}</p></div><section id="papers" class="paper-list" aria-label="{t('文献目录','Publications')}">{''.join(cards)}</section><p id="paper-empty" hidden>{t('试试其他关键词，或重置筛选浏览全部文献。','Try another keyword or reset the filters to browse every publication.')}</p>
<section class="research-notes"><h2>{t('文献与来源','Publications & sources')}</h2><p>{t('研究库在原有 77 条整理记录的基础上，新增眼部交互游戏范围综述中的 85 条非重复文献：63 条经过全文评估，22 条暂依据公开摘要或 HTML 资料收录。证据状态依据贡献者 WeiWu0115 的评估记录标注；每条新增记录标注证据状态，并记录眼部信号、交互角色、系统名称与证据聚类；暂留条目仍需全文核验。','The library adds 85 non-duplicate publications from an interaction-focused scoping review to the 77 previously curated records. Of the additions, 63 were assessed from full text and 22 remain provisional from public abstracts or HTML documentation. Evidence status reflects the assessment recorded by contributor WeiWu0115. Each new record identifies its evidence status and retains coded eye signals, interaction roles, system names and evidence cluster; provisional records still require full-text verification.')}</p><p>{t('书目信息依据 DOI 元数据、可读取的原文与出版方或作者页面整理。原创双语简介概述系统与交互机制，不替代原文中的研究结果。相关游戏仅在能够高置信匹配时建立链接。原创简介采用 CC BY 4.0，原文保留原权利人的授权。','Bibliographic details draw on DOI metadata, readable source documents, and publisher or author pages. Original bilingual summaries describe systems and interaction mechanisms rather than replacing reported results. Related games are linked only when a high-confidence match is available. Original summaries use CC BY 4.0; source publications retain their original rights.')}</p></section>
<section id="contribute-paper" class="research-notes"><h2>{t('一起扩充研究库','Help grow the library')}</h2><p>{t('提交题目、作者、年份、原文或 DOI 链接、简要介绍与相关游戏。维护者核对来源后纳入文献库，并记录贡献者署名。','Suggest a title, authors, year, publication or DOI link, a short description and related games. Maintainers review sources before adding records and crediting contributors.')}</p><div class="paper-links"><a href="https://github.com/sharkburger/eyeTrackingGame_OpenDataBase/issues/new?template={issue}">{t('提交论文','Submit a paper')} ↗</a><a href="https://github.com/sharkburger/eyeTrackingGame_OpenDataBase/blob/main/{'CONTRIBUTING.md' if en else 'CONTRIBUTING.zh-CN.md'}">{t('贡献指南','Contribution guide')} ↗</a></div></section></main><footer><a class="brand" href="./">◉ GAZE ATLAS</a><p>{t('一份关于目光、游戏与研究的开放档案。','An open collection of gaze, games and research.')}</p></footer></body></html>'''
  (directory/path).write_text(content)
 with (ROOT/'data/papers.csv').open('w',encoding='utf-8-sig',newline='') as f:
  fields=list(dict.fromkeys(k for p in papers for k in p));writer=csv.DictWriter(f,fieldnames=fields,lineterminator='\n');writer.writeheader()
  for p in papers:writer.writerow({k:json.dumps(v,ensure_ascii=False) if isinstance(v,list) else v for k,v in p.items()})
if __name__=='__main__':build()
